4	use ecow::{EcoString, EcoVec};
5	use typst_library::diag::{HintedStrResult, SourceResult, StrResult, bail};
6	use typst_library::engine::Engine;
7	use typst_library::foundations::{
8	    Content, Dict, Fold, Output, Repr, Str, StyleChain, Target, cast,
9	};
10	use typst_library::introspection::{Introspector, Location, Tag};
11	use typst_library::layout::{Abs, Frame, Point};
12	use typst_library::model::{Document, DocumentInfo};
13	use typst_library::text::TextElem;
14	use typst_syntax::Span;
15	use typst_utils::{PicoStr, ResolvedPicoStr};
