42	/// The shared implementation of [`html`] and [`html_in_bundle`].
43	fn html_impl(mut w: Writer, root: &HtmlElement) -> SourceResult<String> {
44	    w.buf.push_str("<!DOCTYPE html>");
45	    write_indent(&mut w);
46	    write_element(&mut w, root)?;
