23	pub enum ConversionLevel<'a> {
24	    /// Converts the top-level nodes or children of a block-level element. The
25	    /// conversion has its own local smart quoting state and space protection.
26	    Block,
27	    /// Converts the children of an inline-level HTML element as part of a
28	    /// larger context with shared smart quoting state and shared space
29	    /// protection.
