92	/// Converts one element into HTML node(s).
93	fn handle(
94	    converter: &mut Converter,
95	    child: &Content,
96	    styles: StyleChain,
97	) -> SourceResult<()> {
98	    if let Some(elem) = child.to_packed::<TagElem>() {
99	        converter.push(elem.tag.clone());
100	    } else if let Some(elem) = child.to_packed::<HtmlElem>() {
101	        handle_html_elem(converter, elem, styles)?;
102	    } else if child.is::<SpaceElem>() {
103	        converter.push(HtmlNode::text(' ', child.span()));
104	    } else if let Some(elem) = child.to_packed::<TextElem>() {
105	        let text = if let Some(case) = styles.get(TextElem::case) {
106	            case.apply(&elem.text).into()
107	        } else {
108	            elem.text.clone()
109	        };
110	        handle_text(converter, text, elem.span());
111	    } else if let Some(elem) = child.to_packed::<HElem>()
112	        && elem.amount.is_zero()
113	    {
114	        // Nothing to do for zero-sized spacing. This is sometimes used to
115	        // destruct spaces, e.g. in footnotes. See [`HElem::hole`].
116	    } else if let Some(elem) = child.to_packed::<LinebreakElem>() {
117	        converter.push(match converter.whitespace {
118	            Whitespace::Normal => HtmlElement::new(tag::br).spanned(elem.span()).into(),
119	            Whitespace::Pre => HtmlNode::text("\n", elem.span()),
120	        });
121	    } else if let Some(elem) = child.to_packed::<SmartQuoteElem>() {
122	        let double = elem.double.get(styles);
123	        let quote = if elem.enabled.get(styles) {
124	            let before = last_char(&converter.output);
125	            let quotes = SmartQuotes::get(
126	                elem.quotes.get_ref(styles),
127	                styles.get(TextElem::lang),
128	                styles.get(TextElem::region),
129	                elem.alternative.get(styles),
130	            );
131	            converter.quoter.quote(before, &quotes, double)
132	        } else {
133	            SmartQuotes::fallback(double)
134	        };
135	        handle_text(converter, quote.into(), child.span());
136	    } else if let Some(elem) = child.to_packed::<BoxElem>() {
137	        handle_box(converter, elem, styles)?;
138	    } else if let Some(elem) = child.to_packed::<BlockElem>() {
139	        handle_block(converter, elem, styles)?;
140	    } else if let Some(elem) = child.to_packed::<FrameElem>() {
141	        let locator = converter.locator.next(&elem.span());
142	        let style = TargetElem::target.set(Target::Paged).wrap();
143	        let frame = (converter.engine.library.routines.layout_frame)(
144	            converter.engine,
145	            &elem.body,
146	            locator,
147	            styles.chain(&style),
148	            Region::new(Size::splat(Abs::inf()), Axes::splat(false)),
149	        )?;
150	        let mut node = HtmlFrame::new(frame, styles, elem.span()).into();
151	        // A frame is block-level by default like a Typst `image`. It can
152	        // be wrapped in a `box` to omit the `display` annotation.
153	        make_block_level(&mut node).unwrap();
154	        converter.push(node);
155	    } else {
156	        converter.engine.sink.warn(warning!(
157	            child.span(),
158	            "{} was ignored during HTML export",
159	            child.elem().name(),
160	        ));
161	    }
162	    Ok(())
163	}
