165	/// Handles an HTML element.
166	fn handle_html_elem(
167	    converter: &mut Converter,
168	    elem: &Packed<HtmlElem>,
169	    styles: StyleChain,
170	) -> SourceResult<()> {
171	    // See the docs of `HtmlElem::role` for why we filter out roles for `<p>`
172	    // elements.
173	    let role = styles.get_cloned(HtmlElem::role).filter(|_| elem.tag != tag::p);
174	
175	    let mut children = EcoVec::new();
176	    if let Some(body) = elem.body.get_ref(styles) {
177	        let whitespace = if converter.whitespace == Whitespace::Pre
178	            || elem.tag == tag::pre
179	            || tag::is_raw(elem.tag)
180	            || tag::is_escapable_raw(elem.tag)
181	        {
182	            Whitespace::Pre
183	        } else {
184	            Whitespace::Normal
185	        };
186	
187	        // The `role` attribute should only apply to the first element in the
188	        // hierarchy. Thus, we unset it for children if it is currently set.
189	        let unset;
190	        let styles = if role.is_some() {
191	            unset = HtmlElem::role.set(None).wrap();
192	            styles.chain(&unset)
193	        } else {
194	            styles
195	        };
196	
197	        if property::Display::default_for(elem.tag) == Some(property::Display::Block) {
198	            children = html_block_fragment(
199	                converter.engine,
200	                body,
201	                converter.locator.next(&elem.span()),
202	                styles,
203	                whitespace,
204	            )?;
205	
206	            // Block-level elements reset the inline state. This part is
207	            // unfortunately untested as it's currently not possible to
208	            // create inline-level content next to block-level content
209	            // without a paragraph automatically appearing.
210	            *converter.quoter = SmartQuoter::new();
211	        } else if tag::mathml::is_mathml(elem.tag) {
212	            children = html_math_fragment(
213	                converter.engine,
214	                body,
215	                converter.locator,
216	                converter.quoter,
217	                styles,
218	                whitespace,
219	            )?;
220	        } else {
221	            children = html_inline_fragment(
222	                converter.engine,
223	                body,
224	                converter.locator,
225	                converter.quoter,
226	                styles,
227	                whitespace,
228	            )?;
229	        }
230	    }
231	
232	    let mut attrs = elem.attrs.get_cloned(styles);
233	    if let Some(role) = role {
234	        attrs.push(attr::role, role);
235	    }
236	
237	    converter.push(HtmlElement {
238	        tag: elem.tag,
239	        attrs,
240	        css: elem.css.get_cloned(styles),
241	        children,
242	        parent: elem.parent,
243	        span: elem.span(),
244	        pre_span: false,
245	    });
246	
247	    Ok(())
248	}
