1	//! Conversion from Typst data types into CSS data types.
2	
3	use std::fmt::{Display, Write};
4	use std::ops::Deref;
5	
6	use ecow::{EcoString, EcoVec, eco_format};
7	use typst_library::diag::WarningSink;
8	use typst_library::layout::{Abs, Angle, Em, Length, Ratio, Rel};
9	use typst_library::visualize::{
10	    Color, Hsl, LinearRgb, Oklab, Oklch, Paint, ProcessColor, Rgb,
11	};
12	use typst_utils::Numeric;
13	
14	use crate::property;
15	
16	/// A list of CSS properties with values.
17	#[derive(Debug, Default, Clone, Eq, PartialEq, Hash)]
18	pub struct Properties(EcoVec<Property>);
19	
20	impl Properties {
21	    /// Creates an empty list.
22	    pub fn new() -> Self {
23	        Self::default()
24	    }
25	
26	    /// Creates a builder for adding properties that implement `ToCss`.
27	    pub fn build<S: WarningSink>(sink: S) -> PropertiesBuilder<S> {
28	        PropertiesBuilder::new(sink)
29	    }
30	
31	    /// Adds a new, already serialized property to the list.
32	    pub fn push(&mut self, property: &'static str, value: impl Into<EcoString>) {
33	        let property = Property::new(property, value.into());
34	        let res = self.0.binary_search_by_key(&property.name, |p| p.name);
35	        match res {
36	            Ok(idx) => self.0.make_mut()[idx] = property,
37	            Err(idx) => self.0.insert(idx, property),
38	        }
39	    }
40	
41	    /// Removes a property if it exists.
42	    pub fn remove(&mut self, property: &'static str) {
43	        if let Ok(i) = self.0.binary_search_by_key(&property, |p| p.name) {
44	            self.0.remove(i);
45	        }
46	    }
47	
48	    /// Adds a new, already serialized property in builder style.
49	    pub fn with(mut self, property: &'static str, value: impl Into<EcoString>) -> Self {
50	        self.push(property, value);
51	        self
52	    }
53	
54	    /// Converts the CSS properties into an inline style.
55	    pub fn to_inline(&self) -> impl Display + use<'_> {
56	        typst_utils::display(move |f| {
57	            for (i, Property { name, value }) in self.iter().enumerate() {
58	                if i > 0 {
59	                    f.write_str("; ")?;
60	                }
61	                write!(f, "{name}: {value}")?;
62	            }
63	            Ok(())
64	        })
65	    }
66	}
67	
68	impl Deref for Properties {
69	    type Target = [Property];
70	
71	    fn deref(&self) -> &Self::Target {
72	        &self.0
73	    }
74	}
75	
76	/// A builder for [`Properties`].
77	///
78	/// Allows serializing Typst types into CSS while producing warnings for
79	/// unsupported constructs.
80	#[derive(Debug)]
81	pub struct PropertiesBuilder<S> {
82	    sink: S,
83	    props: Properties,
84	}
85	
86	impl<S: WarningSink> PropertiesBuilder<S> {
87	    /// Create a new builder that emits any warnings that may occur during
88	    /// serialization into the given `sink`.
89	    pub fn new(sink: S) -> Self {
90	        Self { sink, props: Properties::default() }
91	    }
92	
93	    /// Serializes a new property and adds it to the property list.
94	    pub fn push(&mut self, property: &'static str, value: impl ToCss) {
95	        let mut writer = CssWriter::new(&mut self.sink);
96	        writer.emit(value);
97	
98	        if !writer.error {
99	            self.props.push(property, writer.buf);
100	        }
101	    }
102	
103	    /// Serializes a new property and adds it to the property list in builder
104	    /// style.
105	    pub fn with(mut self, property: &'static str, value: impl ToCss) -> Self {
106	        self.push(property, value);
107	        self
108	    }
109	
110	    /// Finish building the properties and propagate warnings.
111	    pub fn finish(self) -> Properties {
112	        self.props
113	    }
114	}
115	
116	/// A CSS property pair such as `display: block`.
117	#[derive(Debug, Clone, Eq, PartialEq, Hash)]
118	pub struct Property {
119	    /// The property's name, e.g. `display`.
120	    // TODO: Use something similar to `HtmlAttr`.
121	    pub name: &'static str,
122	    /// The property's serialized value, e.g. `block`.
123	    pub value: EcoString,
124	}
125	
126	impl Property {
127	    /// Creates a new property pair from its parts.
128	    pub fn new(name: &'static str, value: EcoString) -> Self {
129	        Self { name, value }
130	    }
131	}
132	
133	/// Low-level writer for CSS syntax.
134	pub struct CssWriter<'a> {
135	    sink: &'a mut dyn WarningSink,
136	    buf: EcoString,
137	    error: bool,
138	}
139	
140	impl<'a> CssWriter<'a> {
141	    fn new(sink: &'a mut dyn WarningSink) -> Self {
142	        Self { sink, buf: EcoString::new(), error: false }
143	    }
144	
145	    /// Call a CSS function.
146	    fn call<'b>(&'b mut self, name: &str, separator: Separator) -> CallWriter<'a, 'b> {
147	        CallWriter::start(self, name, separator)
148	    }
149	
150	    /// Start a `calc` call expression.
151	    fn calc<'b>(&'b mut self) -> CalcWriter<'a, 'b> {
152	        CalcWriter::start(self)
153	    }
154	
155	    fn emit(&mut self, value: impl ToCss) {
156	        value.emit(self);
157	    }
158	
159	    fn write(&mut self, value: &str) {
160	        self.buf.push_str(value);
161	    }
162	
163	    fn write_fmt(&mut self, value: impl Display) {
164	        write!(&mut self.buf, "{value}").unwrap();
165	    }
166	
167	    fn ignored(&mut self, what: &str) {
168	        self.sink
169	            .emit(eco_format!("{what} was ignored during HTML export").into());
170	    }
171	
172	    fn fail(&mut self, what: &str) {
173	        self.ignored(what);
174	        self.error = true;
175	    }
176	}
177	
178	/// Writes a CSS function call.
179	struct CallWriter<'a, 'b> {
180	    w: &'b mut CssWriter<'a>,
181	    count: usize,
182	    separator: Separator,
183	}
184	
185	impl<'a, 'b> CallWriter<'a, 'b> {
186	    fn start(w: &'b mut CssWriter<'a>, name: &str, separator: Separator) -> Self {
187	        w.write(name);
188	        w.write("(");
189	        Self { w, count: 0, separator }
190	    }
191	
192	    fn arg(&mut self, value: impl ToCss) -> &mut Self {
193	        self.arg_with(value, self.separator)
194	    }
195	
196	    fn arg_with(&mut self, value: impl ToCss, separator: Separator) -> &mut Self {
197	        if self.count > 0 {
198	            self.w.write(match separator {
199	                Separator::Space => " ",
200	                Separator::Slash => " / ",
201	            });
202	        }
203	        self.w.emit(value);
204	        self.count += 1;
205	        self
206	    }
207	}
208	
209	impl Drop for CallWriter<'_, '_> {
210	    fn drop(&mut self) {
211	        self.w.write(")");
212	    }
213	}
214	
215	/// A separator in a CSS function call argument list.
216	#[derive(Debug, Copy, Clone, Eq, PartialEq)]
217	enum Separator {
218	    Space,
219	    Slash,
220	}
221	
222	/// Writes a lazy CSS `calc(<calc-sum>) expression`.
223	/// If only a single operand is written, `calc(<calc-sum>)` is omitted.
224	struct CalcWriter<'a, 'b> {
225	    w: &'b mut CssWriter<'a>,
226	    /// The byte-index in the [`CssWriter::buf`].
227	    start_idx: usize,
228	    count: usize,
229	}
230	
231	impl<'a, 'b> CalcWriter<'a, 'b> {
232	    fn start(w: &'b mut CssWriter<'a>) -> Self {
233	        let start_idx = w.buf.len();
234	        Self { w, start_idx, count: 0 }
235	    }
236	
237	    /// Add a value.
238	    ///
239	    /// - If it is zero, it will be omitted.
240	    /// - If it is negative, it will be negated and subtracted. This makes the
241	    ///   assumption that the formatted string `"+ {val}"` is equivalent to
242	    ///   `"- {val.neg()}"`.
243	    ///   This would for example not be the case if a value somehow implements
244	    ///   [`Ord`] and would be formatted as a non-parenthesized binary operator
245	    ///   with the same or lower precedence, e.g.
246	    ///   `"+ -1pt + 2em"` != `"- 1pt - 2em"`.
247	    fn sum<T>(&mut self, value: T) -> &mut Self
248	    where
249	        T: ToCss + Numeric + Ord,
250	    {
251	        if value == T::zero() {
252	            return self;
253	        }
254	
255	        if self.count == 0 {
256	            self.w.emit(value);
257	        } else {
258	            // Negate the value and subtract it, in case it is negative.
259	            if value < T::zero() {
260	                self.w.write(" - ");
261	                self.w.emit(value.neg());
262	            } else {
263	                self.w.write(" + ");
264	                self.w.emit(value);
265	            }
266	        }
267	        self.count += 1;
268	        self
269	    }
270	}
271	
272	impl Drop for CalcWriter<'_, '_> {
273	    fn drop(&mut self) {
274	        match self.count {
275	            0 => {
276	                // An empty `calc()` function call is invalid, so write a `0`,
277	                // which is also valid for lengths.
278	                self.w.write("0");
279	            }
280	            1 => (),
281	            2.. => {
282	                // TODO: Use insert_str once merged:
283	                // https://github.com/typst/ecow/pull/59
284	                let mut buf = EcoString::with_capacity(self.w.buf.len() + 6);
285	
286	                // NOTE: This assumes the `ToCss` implementation of all values
287	                // should only modify text that itself has written into the
288	                // buffer, which seems reasonable.
289	                buf.push_str(&self.w.buf[..self.start_idx]);
290	                buf.push_str("calc(");
291	                buf.push_str(&self.w.buf[self.start_idx..]);
292	                buf.push_str(")");
293	
294	                self.w.buf = buf;
295	            }
296	        }
297	    }
298	}
299	
300	/// Serializes a value into CSS.
301	pub trait ToCss {
302	    /// Writes `self` into the writer.
303	    fn emit(&self, w: &mut CssWriter);
304	
305	    /// Convert to a string.
306	    fn to_css(&self, mut sink: impl WarningSink) -> EcoString {
307	        let mut w = CssWriter::new(&mut sink);
308	        self.emit(&mut w);
309	        w.buf
310	    }
311	}
312	
313	impl<T: ToCss + ?Sized> ToCss for &T {
314	    fn emit(&self, w: &mut CssWriter) {
315	        (**self).emit(w);
316	    }
317	}
318	
319	impl ToCss for str {
320	    fn emit(&self, w: &mut CssWriter) {
321	        w.write(self);
322	    }
323	}
324	
325	/// Displays a number with four significant digits.
326	///
327	/// For a number between 0 and 1, four significant digits give us a precision of
328	/// `1/10_000`, which is more than 12 bits (see [`is_very_close`]).
329	struct Number<T: Into<f64>>(T);
330	
331	impl<T: Into<f64> + Copy> ToCss for Number<T> {
332	    fn emit(&self, w: &mut CssWriter) {
333	        w.emit(NumberWithPrecision(self.0, 4));
334	    }
335	}
336	
337	/// Displays a number with N significant digits.
338	struct NumberWithPrecision<T: Into<f64>>(T, i16);
339	
340	impl<T: Into<f64> + Copy> ToCss for NumberWithPrecision<T> {
341	    fn emit(&self, w: &mut CssWriter) {
342	        w.write_fmt(typst_utils::round_with_precision(self.0.into(), self.1));
343	    }
344	}
345	
346	impl ToCss for Abs {
347	    fn emit(&self, w: &mut CssWriter) {
348	        w.emit(Number(self.to_pt()));
349	        w.write("pt");
350	    }
351	}
352	
353	impl ToCss for Em {
354	    fn emit(&self, w: &mut CssWriter) {
355	        w.emit(Number(self.get()));
356	        w.write("em");
357	    }
358	}
359	
360	impl ToCss for Length {
361	    fn emit(&self, w: &mut CssWriter) {
362	        w.calc().sum(self.em).sum(self.abs);
363	    }
364	}
365	
366	impl ToCss for Angle {
367	    fn emit(&self, w: &mut CssWriter) {
368	        w.emit(Number(self.to_deg()));
