1	//! The typed HTML element API (e.g. `html.div`).
2	//!
3	//! The typed API is backed by generated data derived from the HTML
4	//! specification.
5	
6	use std::fmt::Write;
7	use std::num::{NonZeroI64, NonZeroU64};
8	use std::sync::LazyLock;
9	
10	use bumpalo::Bump;
11	use comemo::Tracked;
12	use ecow::{EcoString, eco_format, eco_vec};
13	use typst_assets::html as data;
14	use typst_library::diag::{At, Hint, HintedStrResult, SourceResult, bail};
15	use typst_library::engine::Engine;
16	use typst_library::foundations::{
17	    Args, Array, AutoValue, CastInfo, Content, Context, Datetime, Dict, Duration,
18	    FromValue, IntoValue, NativeFuncData, NativeFuncPtr, NativeParamInfo, NoneValue,
19	    PositiveF64, Reflect, Scope, Since, Str, Type, Value,
20	};
21	use typst_library::layout::{Axes, Axis, Dir, Length};
22	use typst_library::text::TextElem;
23	use typst_library::visualize::Color;
24	use typst_macros::cast;
25	use typst_syntax::Spanned;
26	
27	use crate::css::ToCss;
28	use crate::{HtmlAttr, HtmlAttrs, HtmlElem, HtmlTag, tag};
29	
30	/// Hook up all typed HTML definitions.
31	pub(super) fn define(html: &mut Scope) {
32	    for data in FUNCS.iter() {
33	        html.define_func_with_data(data);
34	    }
35	}
36	
37	/// Lazily created functions for all typed HTML constructors.
38	static FUNCS: LazyLock<Vec<NativeFuncData>> = LazyLock::new(|| {
39	    // Leaking is okay here. It's not meaningfully different from having
40	    // memory-managed values as `FUNCS` is a static.
41	    let bump = Box::leak(Box::new(Bump::new()));
42	    data::ELEMS.iter().map(|info| create_func_data(info, bump)).collect()
43	});
44	
45	/// Creates metadata for a native HTML element constructor function.
46	fn create_func_data(
47	    element: &'static data::ElemInfo,
48	    bump: &'static Bump,
49	) -> NativeFuncData {
50	    NativeFuncData {
51	        function: NativeFuncPtr(bump.alloc(
52	            move |_: &mut Engine, _: Tracked<Context>, args: &mut Args| {
53	                construct(element, args)
54	            },
55	        )),
56	        name: element.name,
57	        title: {
58	            let title = bump.alloc_str(element.name);
59	            title[0..1].make_ascii_uppercase();
60	            title
61	        },
62	        since: Some(Since::Version([0, 14, 0])),
63	        docs: element.docs,
64	        def_site: None,
65	        keywords: &["typed-html"],
66	        contextual: false,
67	        scope: LazyLock::new(&|| Scope::new()),
68	        params: LazyLock::new(bump.alloc(move || create_param_info(element))),
69	        returns: LazyLock::new(&|| CastInfo::Type(Type::of::<Content>())),
70	    }
71	}
72	
73	/// Creates parameter signature metadata for an element.
74	fn create_param_info(element: &'static data::ElemInfo) -> Vec<NativeParamInfo> {
75	    let mut params = vec![];
76	    for attr in element.attributes() {
77	        params.push(NativeParamInfo {
78	            name: attr.name,
79	            docs: attr.docs,
80	            def_site: None,
81	            input: AttrType::convert(attr.ty).input(),
82	            default: None,
83	            positional: false,
84	            named: true,
85	            variadic: false,
86	            required: false,
87	            settable: false,
88	        });
89	    }
90	    let tag = HtmlTag::constant(element.name);
91	    if !tag::is_void(tag) {
92	        let raw = tag::is_raw(tag);
93	        params.push(NativeParamInfo {
94	            name: "body",
95	            docs: if raw {
96	                "The text content of the HTML element."
97	            } else {
98	                "The contents of the HTML element."
99	            },
100	            def_site: None,
101	            input: CastInfo::Type(if raw {
102	                Type::of::<Str>()
103	            } else {
104	                Type::of::<Content>()
105	            }),
106	            default: None,
107	            positional: true,
108	            named: false,
109	            variadic: false,
110	            required: false,
111	            settable: false,
112	        });
113	    }
114	    params
115	}
116	
117	/// The native constructor function shared by all HTML elements.
118	fn construct(element: &'static data::ElemInfo, args: &mut Args) -> SourceResult<Value> {
119	    let mut attrs = HtmlAttrs::default();
120	    let mut errors = eco_vec![];
121	
122	    args.items.retain(|item| {
123	        let Some(name) = &item.name else { return true };
124	        let Some(attr) = element.get_attr(name) else { return true };
125	
126	        let span = item.value.span;
127	        let value = std::mem::take(&mut item.value.v);
128	        let ty = AttrType::convert(attr.ty);
129	        match ty.cast(value).at(span) {
130	            Ok(Some(string)) => attrs.push(HtmlAttr::constant(attr.name), string),
131	            Ok(None) => {}
132	            Err(diags) => errors.extend(diags),
133	        }
134	
135	        false
136	    });
137	
138	    if !errors.is_empty() {
139	        return Err(errors);
140	    }
141	
142	    let tag = HtmlTag::constant(element.name);
143	    let mut elem = HtmlElem::new(tag);
144	    if !attrs.0.is_empty() {
145	        elem.attrs.set(attrs);
146	    }
147	
148	    if !tag::is_void(tag) {
149	        let body = if tag::is_raw(tag) {
150	            let str = args.eat::<Spanned<Str>>()?;
151	            str.map(|Spanned { v, span }| TextElem::packed(v).spanned(span))
152	        } else {
153	            args.eat::<Content>()?
154	        };
155	
156	        elem.body.set(body);
157	    }
158	
159	    Ok(elem.into_value())
160	}
161	
162	/// A dynamic representation of an attribute's type.
163	///
164	/// See the documentation of [`data::Type`] for more details on variants.
165	enum AttrType {
166	    Presence,
167	    Native(NativeType),
168	    Strings(StringsType),
169	    Union(UnionType),
170	    List(ListType),
171	}
172	
173	impl AttrType {
174	    /// Converts the type definition into a representation suitable for casting
175	    /// and reflection.
176	    const fn convert(ty: data::Type) -> AttrType {
177	        use data::Type;
178	        match ty {
179	            Type::Presence => Self::Presence,
180	            Type::None => Self::of::<NoneValue>(),
181	            Type::NoneEmpty => Self::of::<NoneEmpty>(),
182	            Type::NoneUndefined => Self::of::<NoneUndefined>(),
183	            Type::Auto => Self::of::<AutoValue>(),
184	            Type::TrueFalse => Self::of::<TrueFalseBool>(),
185	            Type::YesNo => Self::of::<YesNoBool>(),
186	            Type::OnOff => Self::of::<OnOffBool>(),
187	            Type::Int => Self::of::<i64>(),
188	            Type::NonNegativeInt => Self::of::<u64>(),
189	            Type::PositiveInt => Self::of::<NonZeroU64>(),
190	            Type::Float => Self::of::<f64>(),
191	            Type::PositiveFloat => Self::of::<PositiveF64>(),
192	            Type::Str => Self::of::<Str>(),
193	            Type::Char => Self::of::<char>(),
194	            Type::Datetime => Self::of::<Datetime>(),
195	            Type::Duration => Self::of::<Duration>(),
196	            Type::Color => Self::of::<Color>(),
197	            Type::HorizontalDir => Self::of::<HorizontalDir>(),
198	            Type::IconSize => Self::of::<IconSize>(),
199	            Type::ImageCandidate => Self::of::<ImageCandidate>(),
200	            Type::SourceSize => Self::of::<SourceSize>(),
201	            Type::Strings(start, end) => Self::Strings(StringsType { start, end }),
202	            Type::Union(variants) => Self::Union(UnionType(variants)),
203	            Type::List(inner, separator, shorthand) => {
204	                Self::List(ListType { inner, separator, shorthand })
205	            }
206	        }
207	    }
208	
209	    /// Produces the dynamic representation of an attribute type backed by a
210	    /// native Rust type.
211	    const fn of<T: IntoAttr>() -> Self {
212	        Self::Native(NativeType::of::<T>())
213	    }
214	
215	    /// See [`Reflect::input`].
216	    fn input(&self) -> CastInfo {
217	        match self {
218	            Self::Presence => bool::input(),
219	            Self::Native(ty) => (ty.input)(),
220	            Self::Union(ty) => ty.input(),
221	            Self::Strings(ty) => ty.input(),
222	            Self::List(ty) => ty.input(),
223	        }
224	    }
225	
226	    /// See [`Reflect::castable`].
227	    fn castable(&self, value: &Value) -> bool {
228	        match self {
229	            Self::Presence => bool::castable(value),
230	            Self::Native(ty) => (ty.castable)(value),
231	            Self::Union(ty) => ty.castable(value),
232	            Self::Strings(ty) => ty.castable(value),
233	            Self::List(ty) => ty.castable(value),
234	        }
235	    }
236	
237	    /// Tries to cast the value into this attribute's type and serialize it into
238	    /// an HTML attribute string.
239	    fn cast(&self, value: Value) -> HintedStrResult<Option<EcoString>> {
240	        match self {
241	            Self::Presence => value.cast::<bool>().map(|b| b.then(EcoString::new)),
242	            Self::Native(ty) => (ty.cast)(value),
243	            Self::Union(ty) => ty.cast(value),
244	            Self::Strings(ty) => ty.cast(value),
245	            Self::List(ty) => ty.cast(value),
246	        }
247	    }
248	}
249	
250	/// An enumeration with generated string variants.
251	///
252	/// `start` and `end` are used to index into `data::ATTR_STRINGS`.
253	struct StringsType {
254	    start: usize,
255	    end: usize,
256	}
257	
258	impl StringsType {
259	    fn input(&self) -> CastInfo {
260	        CastInfo::Union(
261	            self.strings()
262	                .iter()
263	                .map(|(val, desc)| CastInfo::Value(val.into_value(), desc))
264	                .collect(),
265	        )
266	    }
267	
268	    fn castable(&self, value: &Value) -> bool {
269	        match value {
270	            Value::Str(s) => self.strings().iter().any(|&(v, _)| v == s.as_str()),
271	            _ => false,
272	        }
273	    }
274	
275	    fn cast(&self, value: Value) -> HintedStrResult<Option<EcoString>> {
276	        if self.castable(&value) {
277	            value.cast().map(Some)
278	        } else {
279	            Err(self.input().error(&value))
280	        }
281	    }
282	
283	    fn strings(&self) -> &'static [(&'static str, &'static str)] {
284	        &data::ATTR_STRINGS[self.start..self.end]
285	    }
286	}
287	
288	/// A type that accepts any of the contained types.
289	struct UnionType(&'static [data::Type]);
290	
291	impl UnionType {
292	    fn input(&self) -> CastInfo {
293	        CastInfo::Union(self.iter().map(|ty| ty.input()).collect())
294	    }
295	
296	    fn castable(&self, value: &Value) -> bool {
297	        self.iter().any(|ty| ty.castable(value))
298	    }
299	
300	    fn cast(&self, value: Value) -> HintedStrResult<Option<EcoString>> {
301	        for item in self.iter() {
302	            if item.castable(&value) {
303	                return item.cast(value);
304	            }
305	        }
306	        Err(self.input().error(&value))
307	    }
308	
309	    fn iter(&self) -> impl Iterator<Item = AttrType> {
310	        self.0.iter().map(|&ty| AttrType::convert(ty))
311	    }
312	}
313	
314	/// A list of items separated by a specific separator char.
315	///
316	/// - <https://html.spec.whatwg.org/#space-separated-tokens>
317	/// - <https://html.spec.whatwg.org/#comma-separated-tokens>
318	struct ListType {
319	    inner: &'static data::Type,
320	    separator: char,
321	    shorthand: bool,
322	}
323	
324	impl ListType {
325	    fn input(&self) -> CastInfo {
326	        if self.shorthand {
327	            Array::input() + self.inner().input()
328	        } else {
329	            Array::input()
330	        }
331	    }
332	
333	    fn castable(&self, value: &Value) -> bool {
334	        Array::castable(value) || (self.shorthand && self.inner().castable(value))
335	    }
336	
337	    fn cast(&self, value: Value) -> HintedStrResult<Option<EcoString>> {
338	        let ty = self.inner();
339	        if Array::castable(&value) {
340	            let array = value.cast::<Array>()?;
341	            let mut out = EcoString::new();
342	            for (i, item) in array.into_iter().enumerate() {
343	                let item = ty.cast(item)?.unwrap();
344	                if item.as_str().contains(self.separator) {
345	                    let buf;
346	                    let name = match self.separator {
347	                        ' ' => "space",
348	                        ',' => "comma",
349	                        _ => {
350	                            buf = eco_format!("'{}'", self.separator);
351	                            buf.as_str()
352	                        }
353	                    };
354	                    bail!(
355	                        "array item may not contain a {name}";
356	                        hint: "the array attribute will be encoded as a \
357	                               {name}-separated string";
358	                    );
359	                }
360	                if i > 0 {
361	                    out.push(self.separator);
362	                    if self.separator == ',' {
363	                        out.push(' ');
364	                    }
365	                }
366	                out.push_str(&item);
367	            }
368	            Ok(Some(out))
369	        } else if self.shorthand && ty.castable(&value) {
370	            let item = ty.cast(value)?.unwrap();
371	            Ok(Some(item))
372	        } else {
373	            Err(self.input().error(&value))
374	        }
375	    }
376	
377	    fn inner(&self) -> AttrType {
378	        AttrType::convert(*self.inner)
379	    }
380	}
381	
382	/// A dynamic representation of attribute backed by a native type implementing
383	/// - the standard `Reflect` and `FromValue` traits for casting from a value,
384	/// - the special `IntoAttr` trait for conversion into an attribute string.
385	#[derive(Copy, Clone)]
386	struct NativeType {
387	    input: fn() -> CastInfo,
388	    cast: fn(Value) -> HintedStrResult<Option<EcoString>>,
389	    castable: fn(&Value) -> bool,
390	}
391	
392	impl NativeType {
393	    /// Creates a dynamic native type from a native Rust type.
394	    const fn of<T: IntoAttr>() -> Self {
395	        Self {
396	            cast: |value| {
397	                let this = value.cast::<T>()?;
398	                Ok(Some(this.into_attr()))
399	            },
400	            input: T::input,
401	            castable: T::castable,
402	        }
403	    }
404	}
405	
406	/// Casts a native type into an HTML attribute.
407	pub trait IntoAttr: FromValue {
408	    /// Turn the value into an attribute string.
409	    fn into_attr(self) -> EcoString;
410	}
411	
412	impl IntoAttr for Str {
413	    fn into_attr(self) -> EcoString {
414	        self.into()
415	    }
416	}
417	
418	/// A boolean that is encoded as a string:
419	/// - `false` is encoded as `"false"`
420	/// - `true` is encoded as `"true"`
421	pub struct TrueFalseBool(pub bool);
422	
423	cast! {
424	    TrueFalseBool,
425	    v: bool => Self(v),
426	}
427	
428	impl IntoAttr for TrueFalseBool {
429	    fn into_attr(self) -> EcoString {
430	        if self.0 { "true" } else { "false" }.into()
431	    }
432	}
433	
434	/// A boolean that is encoded as a string:
435	/// - `false` is encoded as `"no"`
436	/// - `true` is encoded as `"yes"`
437	pub struct YesNoBool(pub bool);
438	
439	cast! {
440	    YesNoBool,
441	    v: bool => Self(v),
442	}
443	
444	impl IntoAttr for YesNoBool {
445	    fn into_attr(self) -> EcoString {
446	        if self.0 { "yes" } else { "no" }.into()
447	    }
448	}
449	
450	/// A boolean that is encoded as a string:
451	/// - `false` is encoded as `"off"`
452	/// - `true` is encoded as `"on"`
453	pub struct OnOffBool(pub bool);
454	
455	cast! {
456	    OnOffBool,
457	    v: bool => Self(v),
458	}
459	
460	impl IntoAttr for OnOffBool {
461	    fn into_attr(self) -> EcoString {
462	        if self.0 { "on" } else { "off" }.into()
463	    }
464	}
465	
466	impl IntoAttr for AutoValue {
467	    fn into_attr(self) -> EcoString {
468	        "auto".into()
469	    }
470	}
471	
472	impl IntoAttr for NoneValue {
473	    fn into_attr(self) -> EcoString {
474	        "none".into()
475	    }
476	}
