478	/// A `none` value that turns into an empty string attribute.
479	struct NoneEmpty;
480	
481	cast! {
482	    NoneEmpty,
483	    _: NoneValue => NoneEmpty,
484	}
485	
486	impl IntoAttr for NoneEmpty {
487	    fn into_attr(self) -> EcoString {
488	        "".into()
489	    }
490	}
491	
492	/// A `none` value that turns into the string `"undefined"`.
493	struct NoneUndefined;
494	
495	cast! {
496	    NoneUndefined,
497	    _: NoneValue => NoneUndefined,
498	}
499	
500	impl IntoAttr for NoneUndefined {
501	    fn into_attr(self) -> EcoString {
502	        "undefined".into()
503	    }
504	}
505	
506	impl IntoAttr for char {
507	    fn into_attr(self) -> EcoString {
508	        eco_format!("{self}")
509	    }
510	}
511	
512	impl IntoAttr for i64 {
513	    fn into_attr(self) -> EcoString {
514	        eco_format!("{self}")
515	    }
516	}
517	
518	impl IntoAttr for u64 {
519	    fn into_attr(self) -> EcoString {
520	        eco_format!("{self}")
521	    }
522	}
523	
524	impl IntoAttr for NonZeroI64 {
525	    fn into_attr(self) -> EcoString {
526	        eco_format!("{self}")
527	    }
528	}
529	
530	impl IntoAttr for NonZeroU64 {
531	    fn into_attr(self) -> EcoString {
532	        eco_format!("{self}")
533	    }
534	}
535	
536	impl IntoAttr for f64 {
537	    fn into_attr(self) -> EcoString {
538	        // HTML float literal allows all the things that Rust's float `Display`
539	        // impl produces.
540	        eco_format!("{self}")
541	    }
542	}
