544	impl IntoAttr for PositiveF64 {
545	    fn into_attr(self) -> EcoString {
546	        self.get().into_attr()
547	    }
548	}
549	
550	impl IntoAttr for Color {
551	    fn into_attr(self) -> EcoString {
552	        // TODO: Warnings are currently ignored.
553	        self.to_css(())
554	    }
555	}
556	
557	impl IntoAttr for Duration {
558	    fn into_attr(self) -> EcoString {
559	        // https://html.spec.whatwg.org/#valid-duration-string
560	        let mut out = EcoString::new();
561	        macro_rules! part {
562	            ($s:literal) => {
563	                if !out.is_empty() {
564	                    out.push(' ');
565	                }
566	                write!(out, $s).unwrap();
567	            };
568	        }
569	
570	        let [weeks, days, hours, minutes, seconds] = self.decompose();
571	        if weeks > 0 {
572	            part!("{weeks}w");
573	        }
574	        if days > 0 {
575	            part!("{days}d");
576	        }
577	        if hours > 0 {
578	            part!("{hours}h");
579	        }
580	        if minutes > 0 {
581	            part!("{minutes}m");
582	        }
583	        if seconds > 0 || out.is_empty() {
584	            part!("{seconds}s");
585	        }
586	
587	        out
588	    }
589	}
