627	/// A direction on the X axis: `ltr` or `rtl`.
628	pub struct HorizontalDir(Dir);
629	
630	cast! {
631	    HorizontalDir,
632	    v: Dir => {
633	        if v.axis() == Axis::Y {
634	            bail!("direction must be horizontal");
635	        }
636	        Self(v)
637	    },
638	}
639	
640	impl IntoAttr for HorizontalDir {
641	    fn into_attr(self) -> EcoString {
642	        self.0.into_attr()
643	    }
644	}
645	
646	impl IntoAttr for Dir {
647	    fn into_attr(self) -> EcoString {
648	        match self {
649	            Self::LTR => "ltr".into(),
650	            Self::RTL => "rtl".into(),
651	            Self::TTB => "ttb".into(),
652	            Self::BTT => "btt".into(),
653	        }
654	    }
655	}
656	
657	/// A width/height pair for `<link rel="icon" sizes="..." />`.
658	pub struct IconSize(Axes<u64>);
659	
660	cast! {
661	    IconSize,
662	    v: Axes<u64> => Self(v),
663	}
664	
665	impl IntoAttr for IconSize {
666	    fn into_attr(self) -> EcoString {
667	        eco_format!("{}x{}", self.0.x, self.0.y)
668	    }
669	}
670	
671	/// <https://html.spec.whatwg.org/#image-candidate-string>
672	pub struct ImageCandidate(EcoString);
673	
674	cast! {
675	    ImageCandidate,
676	    mut v: Dict => {
677	        let src = v.take("src")?.cast::<EcoString>()?;
678	        let width: Option<NonZeroU64> =
679	            v.take("width").ok().map(Value::cast).transpose()?;
680	        let density: Option<PositiveF64> =
681	            v.take("density").ok().map(Value::cast).transpose()?;
682	        v.finish(&["src", "width", "density"])?;
683	
684	        if src.is_empty() {
685	            bail!("`src` must not be empty");
686	        } else if src.starts_with(',') || src.ends_with(',') {
687	            bail!("`src` must not start or end with a comma");
688	        }
689	
690	        let mut out = src;
691	        match (width, density) {
692	            (None, None) => {}
693	            (Some(width), None) => write!(out, " {width}w").unwrap(),
694	            (None, Some(density)) => write!(out, " {}d", density.get()).unwrap(),
695	            (Some(_), Some(_)) => bail!("cannot specify both `width` and `density`"),
696	        }
697	
698	        Self(out)
699	    },
700	}
701	
702	impl IntoAttr for ImageCandidate {
703	    fn into_attr(self) -> EcoString {
704	        self.0
705	    }
706	}
