715	        let size = v
716	            .take("size")?
717	            .cast::<Length>()
718	            .hint("CSS lengths that are not expressible as Typst lengths are not yet supported")
719	            .hint("you can use `html.elem` to create a raw attribute")?;
720	        Self(eco_format!("({condition}) {}", size.to_css(())))
721	    },
722	}
